 function practice(){const L=current,r=C.resolve(st.read(),L);if(!r.ok)return header('Gespeicherte Runde bleibt erhalten')+'<div class="mk-alert"><p>Der Inhalt hat sich ge\u00e4ndert oder diese Runde geh\u00f6rt zu einem anderen Lernweg. Keine automatische Neubewertung.</p>'+button('export','Runde sichern')+button('restart','Neue Runde bewusst starten')+'</div>'+foot();const s=r.session;
 if(s.phase==='finished'){const done=Object.values(s.submitted),ok=done.filter(a=>a.correct).length,open=s.questionIds.length-done.length;return header('F\u00fcr heute etwas gekl\u00e4rt.')+'<section class="mk-next"><h2>'+ok+' von '+s.questionIds.length+' richtig beantwortet</h2><p>'+open+' ausgelassen. Hilfen und Wiederholungen bleiben getrennt erfasst.</p>'+button('open','Erkl\u00e4rung nochmals ansehen','mk-lime','data-id="'+E(L.id)+'"')+'</section><p>Das ist eine R\u00fcckmeldung zu dieser Runde, kein Nachweis von Pr\u00fcfungsreife.</p>'+button('home','F\u00fcr heute fertig','mk-primary')+sourceList(L)+foot();}
 const q=r.question,measured=['pre','post'].includes(s.mode);let h=header(L.title)+'<div class="mk-reading mk-practice"><div class="mk-kicker">Aufgabe '+(s.index+1)+' von '+s.questionIds.length+' / kein Zeitdruck</div>'+(q.context?'<section class="mk-context"><h2>Material</h2><p>'+E(q.context)+'</p></section>':'')+'<h2>'+E(q.prompt)+'</h2>';
 if(s.phase==='feedback'&&measured){h+='<section class="mk-feedback" tabindex="-1" role="status"><h3>Antwort gespeichert</h3><p>In dieser Erhebungsrunde erscheinen keine Lösungen oder Hinweise zwischen den Aufgaben.</p></section>'+button('next-question','Weiter','mk-primary');}
 else if(s.phase==='feedback'){const a=s.submitted[q.id];h+='<section class="mk-feedback '+(a.correct?'mk-good':'mk-again')+'" tabindex="-1" role="status"><h3>'+(a.correct?'Das passt.':'Hier liegt der Unterschied.')+'</h3><p>'+E(q.explanation)+'</p><p>'+(a.assisted?'Mit Hinweis bearbeitet.':'Ohne angeforderten Hinweis in dieser Aufgabe.')+'</p></section>'+button('next-question','Weiter','mk-primary');}
 else h+=answers(q,s)+'<div class="mk-row">'+button('submit','Antwort pr\u00fcfen','mk-primary')+(measured?'':button('hint','Ein Hinweis'))+button('skip','Weiter ohne Wertung')+'</div>'+(s.helped.includes(q.id)?'<div class="mk-hint"><b>Hinweis</b><p>'+E((q.hints||[])[Math.min(Math.max(0,help-1),(q.hints||[]).length-1)]||'Sieh Dir den passenden Beispielschritt an.')+'</p>'+button('example','Beispiel ansehen')+'</div>':'');
 return h+'<div class="mk-row">'+button('pause','Pause und speichern')+'</div></div>'+foot();}
 function teacher(){const selected=st.read().teacher;return header('Material f\u00fcr eine echte Unterrichtsstunde')+'<p class="mk-lead">Stabile Aufgabensets, Sch\u00fclerfassung und L\u00f6sungen. Ohne Klassenkonto und ohne Sch\u00fclerdaten.</p><div class="mk-row no-print">'+button('worksheet','Arbeitsblatt anzeigen','mk-primary')+button('export-selection','Auswahl als Datei')+'</div><div class="mk-grid">'+lessons.map(L=>'<label class="mk-card"><input type="checkbox" data-teacher="'+E(L.id)+'" '+(selected.includes(L.id)?'checked':'')+'><b>'+E(L.title)+'</b><p>'+E(L.objective)+'</p></label>').join('')+'</div>'+foot();}
