 if(a==='calendar'){try{download('stoffknacker-lerntermin.ics',C.calendar('Stoffknacker: freiwilliger Lerntermin',el.querySelector('#mk-day').value,el.querySelector('#mk-time').value),'text/calendar');}catch(_){root.alert('Bitte Datum und Uhrzeit angeben.');}return;}
